// Error-Workflow, Code-Node "Alert vorbereiten"  –  Mode: "Run Once for Each Item", JavaScript
// Liest die Daten des Error Triggers, erkennt die Fehlerart und baut
// den Log-Eintrag fuer Supabase sowie die Alert-Mail.

const e = $json.execution || {};
const w = $json.workflow || {};

const meldung = e.error?.message || e.error?.description || 'Unbekannter Fehler';
const node = e.lastNodeExecuted || e.error?.node?.name || 'unbekannt';
const workflowName = w.name || 'unbekannter Workflow';

// Fehlerart erkennen -> konkreter Hinweis fuer die Behebung
let hinweis = 'Fehler prüfen';
if (/401|403|unauthori|forbidden|credential|api key|permission/i.test(meldung)) hinweis = 'Credential prüfen';
else if (/402|credit|insufficient/i.test(meldung)) hinweis = 'Guthaben prüfen';
else if (/429|rate limit/i.test(meldung)) hinweis = 'Rate Limit – später erneut versuchen';
else if (/timeout|timed out|ETIMEDOUT|ECONNRESET|ENOTFOUND|connection cannot be established|host/i.test(meldung)) hinweis = 'Timeout / Verbindung prüfen';

const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

return {
  json: {
    // fuer die Tabelle "logs"
    execution_id: String(e.id ?? ''),
    schritt: `${workflowName} / ${node}`,
    level: 'ERROR',
    nachricht: `${hinweis}: ${meldung}`.slice(0, 1000),
    // fuer die Alert-Mail
    betreff: `[ALERT] ${hinweis} – ${workflowName} / ${node}`,
    html:
      `<p><b>Workflow:</b> ${esc(workflowName)}<br>` +
      `<b>Fehlerhafter Node:</b> ${esc(node)}<br>` +
      `<b>Execution-ID:</b> ${esc(e.id)}<br>` +
      `<b>Hinweis:</b> ${esc(hinweis)}</p>` +
      `<p><b>Fehlermeldung:</b><br>${esc(meldung)}</p>` +
      (e.url ? `<p><a href="${esc(e.url)}">Execution in n8n öffnen</a></p>` : ''),
  },
};
